   !> DPCM, original form (point charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_original_point_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call dpcm_original_point_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, &
                          "[dpcm_original_point_response] call dpcm_original_point_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_point_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                               hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_point_response

   !> One direction of dpcm_original_point_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s3
      state%op1%c3 => state%s11
      tmp1 = 0.0_wp
      call state%solver%solve(state%op1, .false., dvn, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%s13*tmp1
      tmp2 = 0.0_wp
      call state%solver%solve(state%op1, .true., dv, tmp2, error)
      if (allocated(error)) return
      hvp_vn = state%s13*tmp2
   end subroutine dpcm_original_point_response_one

   !> DPCM, original form (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs dpcm_original_point_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_medium(state, eps, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      if (state%matrix_free) then
         call dpcm_original_point_complex_mf_medium(state, eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_medium] call dpcm_original_point_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s12)) deallocate (state%cx_s12)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s16)) deallocate (state%cx_s16)
      if (allocated(state%cx_s17)) deallocate (state%cx_s17)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (allocated(state%cx_s22)) deallocate (state%cx_s22)
      if (allocated(state%cx_s23)) deallocate (state%cx_s23)
      if (allocated(state%cx_s5)) deallocate (state%cx_s5)
      if (allocated(state%cx_s6)) deallocate (state%cx_s6)
      if (allocated(state%cx_s7)) deallocate (state%cx_s7)
      if (allocated(state%cx_s8)) deallocate (state%cx_s8)
      if (allocated(state%cx_s9)) deallocate (state%cx_s9)
      if (allocated(state%cx_s10)) deallocate (state%cx_s10)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s12(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s16(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s17(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s22(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s23(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_medium] allocation failed")
         return
      end if
      state%cx_s12 = 0.0_wp
      state%cx_s14 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op3%npt = npt
      state%op3%npoint = npt
      state%op3%id = 3
      state%op3%points => state%r
      state%op3%c1 => state%s3
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s4 = -state%cx_s2
      state%op3%c2 = state%cx_s4
      state%op3%c3 => state%s11
      call state%solver%setup_complex(state%op3, error)
      if (allocated(error)) return
      state%cx_s13 = 0.5_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine dpcm_original_point_complex_medium

   !> DPCM, original form (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs dpcm_original_point_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      complex(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      complex(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp5(:), tmp6(:)
      complex(wp), allocatable :: tmp2(:), tmp3(:), tmp4(:), tmp7(:), tmp8(:), tmp9(:), tmp10(:)
      complex(wp) :: tmp1, tmp11

      if (state%matrix_free) then
         call dpcm_original_point_complex_mf_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_solve] call dpcm_original_point_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_solve] vn: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op3%points => state%r
      state%op3%c1 => state%s3
      state%op3%c3 => state%s11
      state%cx_v = v
      call state%solver%solve_complex(state%op3, .false., vn, state%cx_s12, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op3, .true., state%cx_v, state%cx_s14, error)
      if (allocated(error)) return
      q = state%cx_s2*state%cx_s12
      tmp1 = sum(state%cx_v*q)
      energy = 0.5_wp*tmp1
      grad_v = state%cx_s13*state%cx_s12
      grad_vn = state%cx_s13*state%cx_s14
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp2 = state%s3*state%cx_s12
         tmp3 = 6.283185307179586_wp*tmp2
         call gemv(state%s11, real(state%cx_s12, wp), tmp5, trans="t")
         call gemv(state%s11, aimag(state%cx_s12), tmp6, trans="t")
         tmp4 = cmplx(tmp5, tmp6, wp)
         tmp7 = state%cx_s4*tmp4
         tmp8 = tmp3 + tmp7
         tmp9 = -tmp8
         tmp10 = vn + tmp9
         tmp11 = sum(grad_vn*tmp10)
         energy = energy + tmp11
      end if

      state%cx_ready = 3
   end subroutine dpcm_original_point_complex_solve

   !> DPCM, original form (point charges): energy gradient with respect to the other inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs dpcm_original_point_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, &
                                                  grad_eps, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      complex(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      complex(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      complex(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      complex(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      complex(wp), contiguous, intent(out) :: grad_a(:)
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp95(:), tmp96(:)
      real(wp) :: tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, &
                  tmp14, tmp15
      complex(wp), allocatable :: tmp16(:), tmp17(:), tmp18(:), tmp19(:), tmp20(:), tmp21(:), &
                                  tmp88(:), tmp89(:), tmp90(:), tmp93(:), tmp94(:)
      complex(wp) :: tmp1, tmp91, tmp92, tmp97, tmp98, tmp99, tmp100, tmp101
      integer :: i, j

      if (state%matrix_free) then
         call dpcm_original_point_complex_mf_weights(state, grad_r, grad_n, grad_k1, grad_k2, &
                                                     grad_a, grad_eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_weights] call dpcm_original_point_complex_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_n) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_weights] grad_n: wrong shape")
         return
      end if
      if (any(shape(grad_k1) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_weights] grad_k1: wrong shape")
         return
      end if
      if (any(shape(grad_k2) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_weights] grad_k2: wrong shape")
         return
      end if
      if (any(shape(grad_a) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_weights] grad_a: wrong shape")
         return
      end if
      allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp88(npt), stat=stat)
      if (stat == 0) allocate (tmp89(npt), stat=stat)
      if (stat == 0) allocate (tmp90(npt), stat=stat)
      if (stat == 0) allocate (tmp93(npt), stat=stat)
      if (stat == 0) allocate (tmp94(npt), stat=stat)
      if (stat == 0) allocate (tmp95(npt), stat=stat)
      if (stat == 0) allocate (tmp96(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_weights] allocation failed")
         return
      end if
      state%cx_ready = 3

      state%op3%points => state%r
      state%op3%c1 => state%s3
      state%op3%c3 => state%s11
      tmp1 = state%cx_s2**(2)
      state%cx_s15 = 0.5_wp*tmp1
      state%cx_s16 = state%cx_s15*state%cx_s14
      state%cx_s17 = state%cx_s12*state%cx_s16
      do i = 1, npt
         tmp2 = 1.0_wp/state%a(i)
         tmp3 = 12.566370614359172_wp*tmp2
         tmp4 = sqrt(tmp3)
         tmp5 = (-0.26735_wp)*tmp4
         state%cx_s18(i) = tmp5
      end do
      do i = 1, npt
         tmp6 = 1.0_wp/state%a(i)
         tmp7 = 12.566370614359172_wp*tmp6
         tmp8 = 1.0_wp/sqrt(tmp7)
         tmp9 = state%k1(i) + state%k2(i)
         tmp10 = tmp8*tmp9
         tmp11 = state%a(i)**(-2)
         tmp12 = tmp10*tmp11
         tmp13 = 1.6798095918744622_wp*tmp12
         state%cx_s19(i) = tmp13
      end do
      state%cx_s20 = (-3.141592653589793_wp)*state%cx_s2
      state%cx_s21 = state%cx_s20*state%cx_s14
      state%cx_s22 = state%cx_s21*state%cx_s12
      do i = 1, npt
         tmp14 = state%a(i)**(-2)
         tmp15 = -tmp14
         state%cx_s23(i) = tmp15
      end do
      tmp16 = 0.0_wp
      tmp17 = 0.0_wp
      tmp18 = 0.0_wp
      tmp19 = 0.0_wp
      tmp20 = 0.0_wp
      tmp21 = 0.0_wp
      !$omp parallel &
      !$omp& private(i, j) &
      !$omp& shared(npt, state, tmp19, tmp20, tmp21) &
      !$omp& reduction(+: tmp16, tmp17, tmp18)
      block
         real(wp) :: tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, tmp36, tmp39, tmp43
         complex(wp) :: tmp34, tmp35, tmp22, tmp23, tmp24, tmp25, tmp26, tmp27

         !$omp do schedule(static)
         do j = 1, npt
            tmp28 = state%s5(j)
            tmp29 = state%s6(j)
            tmp30 = state%s7(j)
            tmp31 = state%s8(j)
            tmp32 = state%s9(j)
            tmp33 = state%s10(j)
            tmp34 = state%cx_s16(j)
            tmp35 = state%cx_s12(j)
            tmp36 = -tmp29
            tmp39 = -tmp30
            tmp43 = -tmp32
            tmp22 = 0.0_wp
            tmp23 = 0.0_wp
            tmp24 = 0.0_wp
            tmp25 = 0.0_wp
            tmp26 = 0.0_wp
            tmp27 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp22, tmp23, tmp24, tmp25, tmp26, tmp27)
            do i = 1, j - 1
               block
                  real(wp) :: tmp37, tmp38, tmp40, tmp41, tmp42, tmp44, tmp45, tmp46, tmp47, &
                              tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, tmp56, &
                              tmp57, tmp58, tmp59, tmp63, tmp64, tmp65, tmp66, tmp67, tmp71, &
                              tmp72, tmp73, tmp74, tmp75
                  complex(wp) :: tmp60, tmp61, tmp62, tmp68, tmp69, tmp70, tmp76, tmp77, tmp78, &
                                 tmp79, tmp80, tmp81, tmp82, tmp83, tmp84, tmp85, tmp86, tmp87

                  tmp37 = state%s6(i) + tmp36
                  tmp38 = tmp28*tmp37
                  tmp40 = state%s7(i) + tmp39
                  tmp41 = tmp40*tmp31
                  tmp42 = tmp38 + tmp41
                  tmp44 = state%s9(i) + tmp43
                  tmp45 = tmp44*tmp33
                  tmp46 = tmp42 + tmp45
                  tmp47 = tmp46*tmp37
                  tmp48 = tmp37**(2)
                  tmp49 = tmp40**(2)
                  tmp50 = tmp48 + tmp49
                  tmp51 = tmp44**(2)
                  tmp52 = tmp50 + tmp51
                  tmp53 = 1.0_wp/sqrt(tmp52)
                  tmp54 = tmp53**(5)
                  tmp55 = tmp47*tmp54
                  tmp56 = (-3.0_wp)*tmp55
                  tmp57 = tmp53**(3)
                  tmp58 = tmp28*tmp57
                  tmp59 = tmp56 + tmp58
                  tmp60 = tmp59*tmp34
                  tmp61 = tmp60*state%cx_s12(i)
                  tmp16(i) = tmp16(i) + tmp61
                  tmp62 = -tmp61
                  tmp22 = tmp22 + tmp62
                  tmp63 = tmp40*tmp46
                  tmp64 = tmp63*tmp54
                  tmp65 = (-3.0_wp)*tmp64
                  tmp66 = tmp31*tmp57
                  tmp67 = tmp65 + tmp66
                  tmp68 = tmp67*tmp34
                  tmp69 = tmp68*state%cx_s12(i)
                  tmp17(i) = tmp17(i) + tmp69
                  tmp70 = -tmp69
                  tmp23 = tmp23 + tmp70
                  tmp71 = tmp44*tmp46
                  tmp72 = tmp71*tmp54
                  tmp73 = (-3.0_wp)*tmp72
                  tmp74 = tmp33*tmp57
                  tmp75 = tmp73 + tmp74
                  tmp76 = tmp34*tmp75
                  tmp77 = tmp76*state%cx_s12(i)
                  tmp18(i) = tmp18(i) + tmp77
                  tmp78 = -tmp77
                  tmp24 = tmp24 + tmp78
                  tmp79 = tmp34*tmp57
                  tmp80 = tmp79*tmp37
                  tmp81 = tmp80*state%cx_s12(i)
                  tmp25 = tmp25 + tmp81
                  tmp82 = tmp40*tmp34
                  tmp83 = tmp82*tmp57
                  tmp84 = tmp83*state%cx_s12(i)
                  tmp26 = tmp26 + tmp84
                  tmp85 = tmp44*tmp34
                  tmp86 = tmp85*tmp57
                  tmp87 = tmp86*state%cx_s12(i)
                  tmp27 = tmp27 + tmp87
               end block
            end do
            !$omp simd &
            !$omp& reduction(+: tmp22, tmp23, tmp24, tmp25, tmp26, tmp27)
            do i = j + 1, npt
               block
                  real(wp) :: tmp37, tmp38, tmp40, tmp41, tmp42, tmp44, tmp45, tmp46, tmp47, &
                              tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, tmp56, &
                              tmp57, tmp58, tmp59, tmp63, tmp64, tmp65, tmp66, tmp67, tmp71, &
                              tmp72, tmp73, tmp74, tmp75
                  complex(wp) :: tmp60, tmp61, tmp62, tmp68, tmp69, tmp70, tmp76, tmp77, tmp78, &
                                 tmp79, tmp80, tmp81, tmp82, tmp83, tmp84, tmp85, tmp86, tmp87

                  tmp37 = state%s6(i) + tmp36
                  tmp38 = tmp28*tmp37
                  tmp40 = state%s7(i) + tmp39
                  tmp41 = tmp40*tmp31
                  tmp42 = tmp38 + tmp41
                  tmp44 = state%s9(i) + tmp43
                  tmp45 = tmp44*tmp33
                  tmp46 = tmp42 + tmp45
                  tmp47 = tmp46*tmp37
                  tmp48 = tmp37**(2)
                  tmp49 = tmp40**(2)
                  tmp50 = tmp48 + tmp49
                  tmp51 = tmp44**(2)
                  tmp52 = tmp50 + tmp51
                  tmp53 = 1.0_wp/sqrt(tmp52)
                  tmp54 = tmp53**(5)
                  tmp55 = tmp47*tmp54
                  tmp56 = (-3.0_wp)*tmp55
                  tmp57 = tmp53**(3)
                  tmp58 = tmp28*tmp57
                  tmp59 = tmp56 + tmp58
                  tmp60 = tmp59*tmp34
                  tmp61 = tmp60*state%cx_s12(i)
                  tmp16(i) = tmp16(i) + tmp61
                  tmp62 = -tmp61
                  tmp22 = tmp22 + tmp62
                  tmp63 = tmp40*tmp46
                  tmp64 = tmp63*tmp54
                  tmp65 = (-3.0_wp)*tmp64
                  tmp66 = tmp31*tmp57
                  tmp67 = tmp65 + tmp66
                  tmp68 = tmp67*tmp34
                  tmp69 = tmp68*state%cx_s12(i)
                  tmp17(i) = tmp17(i) + tmp69
                  tmp70 = -tmp69
                  tmp23 = tmp23 + tmp70
                  tmp71 = tmp44*tmp46
                  tmp72 = tmp71*tmp54
                  tmp73 = (-3.0_wp)*tmp72
                  tmp74 = tmp33*tmp57
                  tmp75 = tmp73 + tmp74
                  tmp76 = tmp34*tmp75
                  tmp77 = tmp76*state%cx_s12(i)
                  tmp18(i) = tmp18(i) + tmp77
                  tmp78 = -tmp77
                  tmp24 = tmp24 + tmp78
                  tmp79 = tmp34*tmp57
                  tmp80 = tmp79*tmp37
                  tmp81 = tmp80*state%cx_s12(i)
                  tmp25 = tmp25 + tmp81
                  tmp82 = tmp40*tmp34
                  tmp83 = tmp82*tmp57
                  tmp84 = tmp83*state%cx_s12(i)
                  tmp26 = tmp26 + tmp84
                  tmp85 = tmp44*tmp34
                  tmp86 = tmp85*tmp57
                  tmp87 = tmp86*state%cx_s12(i)
                  tmp27 = tmp27 + tmp87
               end block
            end do
            tmp16(j) = tmp16(j) + tmp22
            tmp17(j) = tmp17(j) + tmp23
            tmp18(j) = tmp18(j) + tmp24
            tmp19(j) = tmp19(j) + tmp25
            tmp20(j) = tmp20(j) + tmp26
            tmp21(j) = tmp21(j) + tmp27
         end do
         !$omp end do
      end block
      !$omp end parallel
      grad_r(1, :) = tmp16
      grad_r(2, :) = tmp17
      grad_r(3, :) = tmp18
      grad_n(1, :) = tmp19
      grad_n(2, :) = tmp20
      grad_n(3, :) = tmp21
      grad_k1 = state%cx_s17*state%cx_s18
      grad_k2 = grad_k1
      tmp88 = state%cx_s17*state%cx_s19
      tmp89 = state%cx_s22*state%cx_s23
      grad_a = tmp88 + tmp89
      tmp90 = 0.5_wp*state%cx_v
      tmp91 = sum(tmp90*state%cx_s12)
      tmp92 = (-0.5_wp)*state%cx_s2
      tmp93 = tmp92*state%cx_s14
      call gemv(state%s11, real(state%cx_s12, wp), tmp95, trans="t")
      call gemv(state%s11, aimag(state%cx_s12), tmp96, trans="t")
      tmp94 = cmplx(tmp95, tmp96, wp)
      tmp97 = sum(tmp93*tmp94)
      tmp98 = -tmp97
      tmp99 = tmp91 + tmp98
      tmp100 = state%cx_s1**(-2)
      tmp101 = tmp99*tmp100
      grad_eps = 2.0_wp*tmp101

      state%cx_ready = 4
   end subroutine dpcm_original_point_complex_weights

   !> DPCM, original form (point charges): gradient tangents along blocks of directions
   !>
   !> - Directions of the cavity and QM inputs; for the inputs of the last solve
   !> - Needs dpcm_original_point_complex_weights on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
   !> @param[in] dk1  direction for k1
   !> @param[in] dk2  direction for k2
   !> @param[in] da  direction for a
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_r  hessian times direction, r block
   !> @param[out] hvp_n  hessian times direction, n block
   !> @param[out] hvp_k1  hessian times direction, k1 block
   !> @param[out] hvp_k2  hessian times direction, k2 block
   !> @param[out] hvp_a  hessian times direction, a block
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_tangent(state, dr, dn, dk1, dk2, da, dv, dvn, hvp_r, &
                                                  hvp_n, hvp_k1, hvp_k2, hvp_a, hvp_v, hvp_vn, &
                                                  error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), intent(inout) :: state
      !> Direction for r
      real(wp), contiguous, intent(in) :: dr(:, :, :)
      !> Direction for n
      real(wp), contiguous, intent(in) :: dn(:, :, :)
      !> Direction for k1
      real(wp), contiguous, intent(in) :: dk1(:, :)
      !> Direction for k2
      real(wp), contiguous, intent(in) :: dk2(:, :)
      !> Direction for a
      real(wp), contiguous, intent(in) :: da(:, :)
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, r block
      complex(wp), contiguous, intent(out) :: hvp_r(:, :, :)
      !> Hessian times direction, n block
      complex(wp), contiguous, intent(out) :: hvp_n(:, :, :)
      !> Hessian times direction, k1 block
      complex(wp), contiguous, intent(out) :: hvp_k1(:, :)
      !> Hessian times direction, k2 block
      complex(wp), contiguous, intent(out) :: hvp_k2(:, :)
      !> Hessian times direction, a block
      complex(wp), contiguous, intent(out) :: hvp_a(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call dpcm_original_point_complex_mf_tangent(state, dr, dn, dk1, dk2, da, dv, dvn, hvp_r, &
                                                     hvp_n, hvp_k1, hvp_k2, hvp_a, hvp_v, hvp_vn, &
                                                     error)
         return
      end if
      if (state%cx_ready < 4 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_tangent] call dpcm_original_point_complex_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(da) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_tangent] da: wrong shape")
         return
      end if
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_tangent] dv: wrong shape")
         return
