      tmp28 = 0.0_wp
      tmp29 = 0.0_wp
      tmp30 = 0.0_wp
      !$omp parallel &
      !$omp& private(i, j) &
      !$omp& shared(npt, state, tmp17, tmp28, tmp29, tmp30) &
      !$omp& reduction(+: tmp16, tmp26, tmp27)
      block
         real(wp) :: tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp49, tmp53, &
                     tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37

         !$omp do schedule(static)
         do j = 1, npt
            tmp38 = state%s5(j)
            tmp39 = state%s6(j)
            tmp40 = state%s7(j)
            tmp41 = state%s8(j)
            tmp42 = state%s9(j)
            tmp43 = state%s10(j)
            tmp44 = state%s16(j)
            tmp45 = state%s12(j)
            tmp46 = -tmp39
            tmp49 = -tmp40
            tmp53 = -tmp42
            tmp31 = 0.0_wp
            tmp32 = 0.0_wp
            tmp33 = 0.0_wp
            tmp34 = 0.0_wp
            tmp35 = 0.0_wp
            tmp36 = 0.0_wp
            tmp37 = 0.0_wp
            !$omp simd &
