            do i = 1, j - 1
               block
                  real(wp) :: tmp47, tmp48, tmp50, tmp51, tmp52, tmp54, tmp55, tmp56, tmp57, &
                              tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, tmp66, &
                              tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, tmp74, tmp75, &
                              tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, tmp84, &
                              tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, tmp92, tmp93, &
                              tmp94, tmp95, tmp96, tmp97, tmp98, tmp99

                  tmp47 = state%s6(i) + tmp46
                  tmp48 = tmp38*tmp47
                  tmp50 = state%s7(i) + tmp49
                  tmp51 = tmp50*tmp41
                  tmp52 = tmp48 + tmp51
                  tmp54 = state%s9(i) + tmp53
                  tmp55 = tmp54*tmp43
                  tmp56 = tmp52 + tmp55
                  tmp57 = tmp56*tmp47
                  tmp58 = tmp47**(2)
                  tmp59 = tmp50**(2)
                  tmp60 = tmp58 + tmp59
                  tmp61 = tmp54**(2)
                  tmp62 = tmp60 + tmp61
                  tmp63 = 1.0_wp/sqrt(tmp62)
                  tmp64 = tmp63**(5)
                  tmp65 = tmp57*tmp64
                  tmp66 = (-3.0_wp)*tmp65
                  tmp67 = tmp63**(3)
                  tmp68 = tmp38*tmp67
                  tmp69 = tmp66 + tmp68
                  tmp70 = tmp69*tmp44
                  tmp71 = tmp70*state%s12(i)
                  tmp16(i) = tmp16(i) + tmp71
                  tmp72 = -tmp71
                  tmp31 = tmp31 + tmp72
                  tmp73 = tmp56*tmp67
                  tmp74 = tmp73*state%s12(i)
                  tmp32 = tmp32 + tmp74
                  tmp75 = tmp50*tmp56
                  tmp76 = tmp75*tmp64
                  tmp77 = (-3.0_wp)*tmp76
