   !> DPCM, original form (point charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_original_point_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_mf_response] call dpcm_original_point_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_point_complex_mf_response_one(state, dv(:, blk), dvn(:, blk), &
                                                          hvp_v(:, blk), hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_point_complex_mf_response

   !> One direction of dpcm_original_point_complex_mf_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_complex_mf_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:), tmp2(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, &
                          "[dpcm_original_point_complex_mf_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_complex_mf_response_one] allocation failed")
         return
      end if

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%op4%c1 => state%s3
      tmp1 = 0.0_wp
      call state%solver%solve_complex(state%op4, .false., dvn, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%cx_s13*tmp1
      tmp2 = 0.0_wp
      call state%solver%solve_complex(state%op4, .true., dv, tmp2, error)
      if (allocated(error)) return
      hvp_vn = state%cx_s13*tmp2
   end subroutine dpcm_original_point_complex_mf_response_one

   !> Apply operator 1 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_original_point_op1_apply(self, trans, x, y)
      !> Operator
      class(dpcm_original_point_op1), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp4(self%npt))
            tmp1 = self%c1*x
            tmp2 = 6.283185307179586_wp*tmp1
            call gemv(self%c3, x, tmp3)
            tmp4 = self%c2*tmp3
            y = tmp2 + tmp4
         end block
      else
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp4(self%npt))
            tmp1 = self%c1*x
            tmp2 = 6.283185307179586_wp*tmp1
            call gemv(self%c3, x, tmp3, trans="t")
            tmp4 = self%c2*tmp3
            y = tmp2 + tmp4
         end block
      end if
   end subroutine dpcm_original_point_op1_apply

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine dpcm_original_point_op1_assemble(self, a, error)
      !> Operator
      class(dpcm_original_point_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :), tmp4(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp4(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op1_assemble] allocation failed")
         return
      end if
      tmp1 = 0.0_wp
      do i = 1, self%npt
         tmp1(i, i) = self%c1(i)
      end do
      tmp2 = 6.283185307179586_wp*tmp1
      tmp3 = transpose(self%c3)
      tmp4 = self%c2*tmp3
      a = tmp2 + tmp4
   end subroutine dpcm_original_point_op1_assemble

   !> Form operator 1 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine dpcm_original_point_op1_assemble_block(self, idx, a, error)
      !> Operator
      class(dpcm_original_point_op1), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp), allocatable :: tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :), tmp6(:, :)
      integer :: i

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_original_point_op1_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op1_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%c1(idx)
      tmp2 = self%c3(idx, idx)
      tmp3 = 0.0_wp
      do i = 1, nb
         tmp3(i, i) = tmp1(i)
      end do
      tmp4 = 6.283185307179586_wp*tmp3
      tmp5 = transpose(tmp2)
      tmp6 = self%c2*tmp5
      a = tmp4 + tmp6
   end subroutine dpcm_original_point_op1_assemble_block

   !> Apply operator 2 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_original_point_op2_apply(self, trans, x, y)
      !> Operator
      class(dpcm_original_point_op2), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp11(:), tmp39(:)
            real(wp) :: tmp5, tmp6, tmp7, tmp8, tmp9, tmp10
            integer :: i, j

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp4(self%npt))
            allocate (tmp11(self%npt))
            allocate (tmp39(self%npt))
            tmp1 = self%c1*x
            tmp2 = 6.283185307179586_wp*tmp1
            do i = 1, self%npt
               tmp5 = self%k1(i) + self%k2(i)
               tmp6 = 1.0_wp/self%a(i)
               tmp7 = 12.566370614359172_wp*tmp6
               tmp8 = sqrt(tmp7)
               tmp9 = tmp5*tmp8
               tmp10 = (-0.26735_wp)*tmp9
               tmp4(i) = tmp10
            end do
            tmp11 = tmp4*x
            tmp3 = tmp11
            !$omp parallel &
            !$omp& private(i, j) &
            !$omp& shared(self, x) &
            !$omp& reduction(+: tmp3)
            block
               real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp22, tmp26

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp12 = self%n(1, j)
                  tmp13 = self%r(1, j)
                  tmp14 = self%r(2, j)
                  tmp15 = self%n(2, j)
                  tmp16 = self%r(3, j)
                  tmp17 = self%n(3, j)
                  tmp18 = x(j)
                  tmp19 = -tmp13
                  tmp22 = -tmp14
                  tmp26 = -tmp16
                  !$omp simd
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, &
                                    tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38

                        tmp20 = self%r(1, i) + tmp19
                        tmp21 = tmp12*tmp20
                        tmp23 = self%r(2, i) + tmp22
                        tmp24 = tmp23*tmp15
                        tmp25 = tmp21 + tmp24
                        tmp27 = self%r(3, i) + tmp26
                        tmp28 = tmp27*tmp17
                        tmp29 = tmp25 + tmp28
                        tmp30 = tmp29*tmp18
                        tmp31 = tmp20**(2)
                        tmp32 = tmp23**(2)
                        tmp33 = tmp31 + tmp32
                        tmp34 = tmp27**(2)
                        tmp35 = tmp33 + tmp34
                        tmp36 = 1.0_wp/sqrt(tmp35)
                        tmp37 = tmp36**(3)
                        tmp38 = tmp30*tmp37
                        tmp3(i) = tmp3(i) + tmp38
                     end block
                  end do
                  !$omp simd
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, &
                                    tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38

                        tmp20 = self%r(1, i) + tmp19
                        tmp21 = tmp12*tmp20
                        tmp23 = self%r(2, i) + tmp22
                        tmp24 = tmp23*tmp15
                        tmp25 = tmp21 + tmp24
                        tmp27 = self%r(3, i) + tmp26
                        tmp28 = tmp27*tmp17
                        tmp29 = tmp25 + tmp28
                        tmp30 = tmp29*tmp18
                        tmp31 = tmp20**(2)
                        tmp32 = tmp23**(2)
                        tmp33 = tmp31 + tmp32
                        tmp34 = tmp27**(2)
                        tmp35 = tmp33 + tmp34
                        tmp36 = 1.0_wp/sqrt(tmp35)
                        tmp37 = tmp36**(3)
                        tmp38 = tmp30*tmp37
                        tmp3(i) = tmp3(i) + tmp38
