            tmp11 = tmp4*x
            tmp3 = tmp11
            !$omp parallel &
            !$omp& private(i, j) &
            !$omp& shared(self, tmp3, x)
            block
               real(wp) :: tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp23, tmp27
               complex(wp) :: tmp13, tmp12

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp13 = x(j)
                  tmp14 = self%n(1, j)
                  tmp15 = self%r(1, j)
                  tmp16 = self%r(2, j)
                  tmp17 = self%n(2, j)
                  tmp18 = self%r(3, j)
                  tmp19 = self%n(3, j)
                  tmp20 = -tmp15
                  tmp23 = -tmp16
                  tmp27 = -tmp18
                  tmp12 = 0.0_wp
                  !$omp simd &
                  !$omp& reduction(+: tmp12)
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp21, tmp22, tmp24, tmp25, tmp26, tmp28, tmp29, tmp30, tmp32, &
                                    tmp33, tmp34, tmp35, tmp36, tmp37, tmp38
                        complex(wp) :: tmp31, tmp39

                        tmp21 = self%r(1, i) + tmp20
                        tmp22 = tmp14*tmp21
                        tmp24 = self%r(2, i) + tmp23
                        tmp25 = tmp24*tmp17
                        tmp26 = tmp22 + tmp25
                        tmp28 = self%r(3, i) + tmp27
                        tmp29 = tmp28*tmp19
                        tmp30 = tmp26 + tmp29
                        tmp31 = x(i)*tmp30
                        tmp32 = tmp21**(2)
                        tmp33 = tmp24**(2)
                        tmp34 = tmp32 + tmp33
                        tmp35 = tmp28**(2)
                        tmp36 = tmp34 + tmp35
                        tmp37 = 1.0_wp/sqrt(tmp36)
                        tmp38 = tmp37**(3)
                        tmp39 = tmp31*tmp38
                        tmp12 = tmp12 + tmp39
                     end block
                  end do
                  !$omp simd &
                  !$omp& reduction(+: tmp12)
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp21, tmp22, tmp24, tmp25, tmp26, tmp28, tmp29, tmp30, tmp32, &
                                    tmp33, tmp34, tmp35, tmp36, tmp37, tmp38
                        complex(wp) :: tmp31, tmp39

                        tmp21 = self%r(1, i) + tmp20
                        tmp22 = tmp14*tmp21
                        tmp24 = self%r(2, i) + tmp23
                        tmp25 = tmp24*tmp17
                        tmp26 = tmp22 + tmp25
                        tmp28 = self%r(3, i) + tmp27
                        tmp29 = tmp28*tmp19
                        tmp30 = tmp26 + tmp29
                        tmp31 = x(i)*tmp30
                        tmp32 = tmp21**(2)
                        tmp33 = tmp24**(2)
                        tmp34 = tmp32 + tmp33
                        tmp35 = tmp28**(2)
                        tmp36 = tmp34 + tmp35
                        tmp37 = 1.0_wp/sqrt(tmp36)
                        tmp38 = tmp37**(3)
                        tmp39 = tmp31*tmp38
                        tmp12 = tmp12 + tmp39
                     end block
                  end do
                  tmp3(j) = tmp3(j) + tmp12
               end do
               !$omp end do
            end block
            !$omp end parallel
            tmp40 = self%c2*tmp3
            y = tmp2 + tmp40
         end block
      end if
   end subroutine dpcm_original_point_op4_apply

   !> Form operator 4 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine dpcm_original_point_op4_assemble(self, a, error)
      !> Operator
      class(dpcm_original_point_op4), intent(in) :: self
      !> Dense operator matrix
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :), tmp38(:, :)
      real(wp) :: tmp32, tmp33, tmp34, tmp35, tmp36, tmp37
      complex(wp), allocatable :: tmp39(:, :)
      integer :: i, j

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp38(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp39(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op4_assemble] allocation failed")
         return
      end if
      tmp1 = 0.0_wp
      do i = 1, self%npt
         tmp1(i, i) = self%c1(i)
      end do
      tmp2 = 6.283185307179586_wp*tmp1
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(self, tmp3)
      do j = 1, self%npt
         block
            real(wp) :: tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, &
                        tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, &
                        tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31

            do i = 1, j - 1
               tmp4 = -self%r(1, j)
               tmp5 = self%r(1, i) + tmp4
               tmp6 = self%n(1, j)*tmp5
               tmp7 = -self%r(2, j)
               tmp8 = self%r(2, i) + tmp7
               tmp9 = tmp8*self%n(2, j)
               tmp10 = tmp6 + tmp9
               tmp11 = -self%r(3, j)
               tmp12 = self%r(3, i) + tmp11
               tmp13 = tmp12*self%n(3, j)
               tmp14 = tmp10 + tmp13
               tmp15 = tmp5**(2)
               tmp16 = tmp8**(2)
               tmp17 = tmp15 + tmp16
               tmp18 = tmp12**(2)
               tmp19 = tmp17 + tmp18
               tmp20 = 1.0_wp/sqrt(tmp19)
               tmp21 = tmp20**(3)
               tmp22 = tmp14*tmp21
               tmp3(i, j) = tmp22
               tmp23 = -tmp5
               tmp24 = self%n(1, i)*tmp23
               tmp25 = -tmp8
               tmp26 = tmp25*self%n(2, i)
               tmp27 = tmp24 + tmp26
               tmp28 = -tmp12
               tmp29 = tmp28*self%n(3, i)
               tmp30 = tmp27 + tmp29
               tmp31 = tmp30*tmp21
               tmp3(j, i) = tmp31
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, self%npt
         tmp32 = self%k1(i) + self%k2(i)
         tmp33 = 1.0_wp/self%a(i)
         tmp34 = 12.566370614359172_wp*tmp33
         tmp35 = sqrt(tmp34)
         tmp36 = tmp32*tmp35
         tmp37 = (-0.26735_wp)*tmp36
         tmp3(i, i) = tmp37
      end do
      tmp38 = transpose(tmp3)
      tmp39 = self%c2*tmp38
      a = tmp2 + tmp39
   end subroutine dpcm_original_point_op4_assemble

   !> Form operator 4 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine dpcm_original_point_op4_assemble_block(self, idx, a, error)
      !> Operator
      class(dpcm_original_point_op4), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp5(:), tmp6(:)
      real(wp), allocatable :: tmp7(:, :), tmp8(:, :), tmp9(:, :), tmp44(:, :)
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :)
      real(wp) :: tmp38, tmp39, tmp40, tmp41, tmp42, tmp43
      complex(wp), allocatable :: tmp45(:, :)
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_original_point_op4_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(3, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb), stat=stat)
      if (stat == 0) allocate (tmp7(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp8(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp9(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp44(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp45(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op4_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%n(:, idx)
      tmp3 = self%k1(idx)
      tmp4 = self%k2(idx)
      tmp5 = self%a(idx)
      tmp6 = self%c1(idx)
      tmp7 = 0.0_wp
      do i = 1, nb
         tmp7(i, i) = tmp6(i)
      end do
      tmp8 = 6.283185307179586_wp*tmp7
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(nb, tmp1, tmp2, tmp9)
      do j = 1, nb
         block
            real(wp) :: tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, &
                        tmp20, tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, &
                        tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37

            do i = 1, j - 1
               tmp10 = -tmp1(1, j)
               tmp11 = tmp1(1, i) + tmp10
               tmp12 = tmp2(1, j)*tmp11
               tmp13 = -tmp1(2, j)
               tmp14 = tmp1(2, i) + tmp13
               tmp15 = tmp14*tmp2(2, j)
               tmp16 = tmp12 + tmp15
               tmp17 = -tmp1(3, j)
               tmp18 = tmp1(3, i) + tmp17
               tmp19 = tmp18*tmp2(3, j)
               tmp20 = tmp16 + tmp19
               tmp21 = tmp11**(2)
               tmp22 = tmp14**(2)
               tmp23 = tmp21 + tmp22
               tmp24 = tmp18**(2)
               tmp25 = tmp23 + tmp24
               tmp26 = 1.0_wp/sqrt(tmp25)
               tmp27 = tmp26**(3)
               tmp28 = tmp20*tmp27
               tmp9(i, j) = tmp28
               tmp29 = -tmp11
               tmp30 = tmp2(1, i)*tmp29
               tmp31 = -tmp14
               tmp32 = tmp31*tmp2(2, i)
               tmp33 = tmp30 + tmp32
               tmp34 = -tmp18
               tmp35 = tmp34*tmp2(3, i)
               tmp36 = tmp33 + tmp35
               tmp37 = tmp36*tmp27
               tmp9(j, i) = tmp37
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, nb
         tmp38 = tmp3(i) + tmp4(i)
         tmp39 = 1.0_wp/tmp5(i)
         tmp40 = 12.566370614359172_wp*tmp39
         tmp41 = sqrt(tmp40)
         tmp42 = tmp38*tmp41
         tmp43 = (-0.26735_wp)*tmp42
         tmp9(i, i) = tmp43
      end do
      tmp44 = transpose(tmp9)
      tmp45 = self%c2*tmp44
      a = tmp8 + tmp45
   end subroutine dpcm_original_point_op4_assemble_block

end module pcmgen_point_dpcm_original
